  updated_asc: 'b.updated_at ASC, b.id ASC',
  title_asc: 'b.title COLLATE NOCASE ASC, b.id DESC',
  title_desc: 'b.title COLLATE NOCASE DESC, b.id DESC',
  url_asc: 'b.url COLLATE NOCASE ASC, b.id DESC'
