function viewClause(view) {
  switch (view) {
    case 'unread': return 'b.archived = 0 AND b.unread = 1';
    case 'favorites': return 'b.archived = 0 AND b.favorite = 1';
    case 'archived': return 'b.archived = 1';
    case 'all':
