  // Split into structural tokens to keep folder nesting roughly correct.
  const tokenRe = /<DT>\s*<H3[^>]*>([\s\S]*?)<\/H3>|<\/DL>|<DT>\s*<A\b([^>]*)>([\s\S]*?)<\/A>(?:\s*<DD>([\s\S]*?)(?=<DT>|<\/DL>|$))?/gi;
